styles.css:
/* Sub menu styles */

@media (min-width: 600px) {
    .wp-block-navigation .has-child .wp-block-navigation__submenu-container {
        border-radius: 0;
        font-weight: normal;
        width: 17rem !important;
        margin-left: calc((var(--wp--preset--spacing--medium) * -1) / 2);
        border-top: 1rem solid var(--wp--preset--color--primary) !important;
        border-bottom: 4px solid var(--wp--preset--color--primary) !important;
    }


    .wp-block-navigation .has-child .wp-block-navigation__submenu-container a.wp-block-navigation-item__content {
        font-size: var(--wp--preset--font-size--base) !important;
    }


    header .wp-block-navigation :where(.wp-block-navigation__submenu-container) li:first-child {
        padding-top: calc(var(--wp--preset--spacing--small) * 0.66);
    }

    header .wp-block-navigation :where(.wp-block-navigation__submenu-container) li:last-child {
        padding-bottom: calc(var(--wp--preset--spacing--small) * 0.66);
    }
}


.wp-block-navigation .wp-block-navigation__submenu-icon {
    margin: -6px 0 0 8px;
}





/* Fix submenu toggle icon */

header .wp-block-navigation :where(.wp-block-navigation__submenu-container) a, 
header .wp-block-navigation :where(.wp-block-navigation__submenu-container) .wp-block-navigation-submenu__toggle {
    padding: 12px 26px !important;
}





/* Hover effect for main nav */

.wp-block-navigation :where(a),
.wp-block-navigation :where(a:active),
.wp-block-navigation :where(a:focus) {
    text-decoration: underline;
    text-decoration-color: transparent;
    transition: ease-in-out 240ms all;
}


.wp-block-navigation :where(a:hover) {
    text-decoration-color: currentColor;
    color: var(--wp--preset--color--custom-fruity-orange-dark) !important;
}



/* Mobile subnav positioning  */

@media (max-width: 600px) {
    .is-menu-open.has-modal-open ul.wp-block-navigation-submenu .wp-block-navigation-item__content {
        padding: 4px 0 !important;
        font-weight: normal;
    }

    .is-menu-open.has-modal-open .wp-block-navigation-item .wp-block-navigation__submenu-container {
        margin: 0 0 var(--wp--preset--spacing--medium);
        padding: 0 0 0 var(--wp--preset--spacing--medium) !important;
    }

    .is-menu-open.has-modal-open .wp-block-navigation__container ul li a:before {
        left: calc(var(--wp--preset--spacing--medium) * -1);
    }
}





/**
 * Transitions on all links
 */

a {
    transition: ease-in-out 250ms all;
}





/**
 * Utility class
 */

.u-align-items-normal {
    align-items: normal;
}


.u-full-height {
    height: 100%;
}





/**
 * Align terms
 */

.wp-block-post.type-knowledge-base .wp-block-group-is-layout-flex {
    align-items: flex-start;
}





/**
 * Formidable checkboxes
 */

.frm_style_formidable-style.with_frm_style p.description, 
.frm_style_formidable-style.with_frm_style div.description, 
.frm_style_formidable-style.with_frm_style div.frm_description, 
.frm_style_formidable-style.with_frm_style .frm-show-form > div.frm_description, 
.frm_style_formidable-style.with_frm_style .frm_error, 
.frm_style_formidable-style.with_frm_style .frm_pro_max_limit_desc {
    margin: 1rem 0 0;
    font-size: var(--wp--preset--font-size--small);
}


.with_frm_style .frm_radio label, 
.with_frm_style .frm_checkbox label {
    font-size: var(--wp--preset--font-size--small);
    color: #444444;
}


.with_frm_style .frm_checkbox label input[type=checkbox], 
.with_frm_style .frm_radio label input[type=radio] {
    margin: -0.25rem 0.5rem 0 0;
}


.frm_form_field .frm_checkbox,
.frm_form_field .frm_radio {
    margin: 0.25rem 0;
}





/**
 * Specific Formidable fields
 */

/* Finance options checkboxes */

[id="frm_field_97_container"] .frm_checkbox {
    width: 48%;
}
